// Personal health agents (consumer-facing health AI) tracker. Newest first.
var phaTimelineData = [
  {date:"2026-10-02",cat:"Product",title:"Lifelong Launches Alo, a Family AI Health Assistant for iPhone",desc:"Lifelong introduced Alo, an AI health assistant built into Lifelong, the family health app for iPhone. Alo knows each person in the family, answers from their own records and their own numbers, and proactively flags changes instead of waiting to be asked. Users can talk to Alo in the app or from Messages. Represents the family-centric design pattern for personal health agents, extending the agent concept beyond individual health to household-level health management. Vendor claim: family health assistant, not a medical device.",src:"Lifelong",url:"https://trylifelong.com/blog/introducing-alo",new:true},
  {date:"2026-11-02",cat:"Trend",title:"Sensor Tower: AI Health Insights Reshape Wearable Market as Apps Drive Engagement",desc:"Market intelligence firm Sensor Tower reported that as smart rings and screenless fitness bands move away from displays, competition is shifting toward companion apps that turn sensor data into health insights. WHOOP and Oura are placing greater emphasis on personalised AI-driven health insights, using apps to move beyond displaying individual readings to identifying patterns and recommending actions. The report frames the competitive shift: hardware differentiation is narrowing, and the app-layer AI coach is becoming the product. Vendor claim: market analysis, not product evaluation.",src:"Business Standard / Sensor Tower",url:"https://www.business-standard.com/technology/tech-news/ai-health-insights-reshape-wearable-market-as-apps-drive-engagement-report-126110200859_1.html",new:true},
  {date:"2026-09-18",cat:"Product",title:"BodyBuddy Launches Agentic Health Record Built from Daily Conversations",desc:"BodyBuddy introduced the 'agentic health record,' an AI-maintained health log built from daily text conversations that captures what happens between appointments - knee pain on stairs, digestive issues after lunch, sleep disruption before deadlines, adherence to physio exercises. The record is written from user texts, not EHR data, and covers the gaps that clinical records never see. Represents the conversational-first design pattern for personal health agents: the agent builds the record through ongoing dialogue rather than importing from existing data sources. Vendor claim: agentic health record, not a medical device.",src:"BodyBuddy",url:"https://bodybuddy.app/blog/agentic-health-record"},
    {date:"2026-11-05",cat:"Product",title:"Octo Health Launches Beta Combining 100+ Biomarker Testing with Unified Health Data Timeline",desc:"Octo Health launched a beta platform that brings medical records, lab results, medications and health data into one health timeline. Combines annual testing of 100+ biomarkers with unified health data so members can identify patterns and track health trends over time. Gives consumers greater ownership of their data and helps them understand what it means. Vendor claim: proactive personalized healthcare, not a medical device.",src:"GlobeNewswire / Octo Health",url:"https://www.globenewswire.com/news-release/2026/11/05/3396534/0/en/octo-health-launches-beta-to-make-proactive-personalized-healthcare-more-accessible.html",new:true},
  {date:"2026-11-04",cat:"Product",title:"Felix Health Launches 'Ask Felix' AI Assistant Paired with Human Care Teams",desc:"Canadian digital health company Felix Health launched Ask Felix, an AI assistant that pairs with each patient's Felix human care team to answer care-related questions, act on everyday requests and bring concerns to their healthcare practitioner. Built on Felix's newly published Patient-First AI Principles. Represents a hybrid model where AI extends rather than replaces the care team. Vendor claim: AI assistant integrated with human care team, not a replacement for medical care.",src:"CNW / Felix Health",url:"https://www.newswire.ca/news-releases/most-health-ai-ends-with-talk-to-your-doctor-felix-s-new-ai-assistant-brings-yours-in--855533177.html",new:true},
  {date:"2026-11-04",cat:"Research",title:"Google Publishes Whitepaper on End-to-End Evaluation Framework for Health AI",desc:"Google Research, in partnership with health experts Dr. Elizabeth McGlynn and Dr. Dana Gelb Safran, published a whitepaper detailing an end-to-end evaluation approach for AI in health. The framework evaluates models across three areas: accuracy, safety, and usefulness, combining closed-question benchmarks, autoraters, and expert human review to assess common and high-risk health scenarios. Addresses the evaluation bottleneck as health AI deployment outpaces safety validation.",src:"Google Research Blog",url:"https://blog.google/innovation-and-ai/technology/health/evaluating-health-ai-at-scale/",new:true},
  {date:"2026-11-03",cat:"Product",title:"Apple's Redesigned AI Health App Returns in iOS 27.3 Beta with Insights and Longevity Tabs",desc:"iOS 27.3 reintroduces Apple's redesigned Health app, which was pulled from iOS 27.2 beta in October. Built with Apple Intelligence at its core, the app features an Insights tab with AI-generated summaries and Personal Guidance, and a Longevity tab analyzing longitudinal health data including Health Age. Language support expanded to global English, Chinese, French, Japanese, Korean, Norwegian, Portuguese, Spanish, Turkish and Vietnamese. Available to users as a free software update by end of 2026.",src:"Apple / MacRumors",url:"https://www.apple.com/newsroom/2026/11/redesigned-health-app-expands-language-support/",new:true},
  {date:"2026-11-02",cat:"Research",title:"DiabAgent: Tsinghua Researchers Propose Agentic Physiological Control for Diabetes",desc:"arXiv preprint from Tsinghua University presenting DiabAgent, an agentic system for physiological control in diabetes management. The work extends medical LLMs from answering questions to taking actions that influence physiology, representing a shift from advisory AI to agentic intervention in personal health. Preprint, not peer-reviewed.",src:"arXiv",url:"https://arxiv.org/abs/2611.03601",new:true},
  {date:"2026-11-02",cat:"Research",title:"VCU and Emory Develop HomePal Ambient Sensor System to Detect Loneliness in Older Adults",desc:"Researchers at Virginia Commonwealth University and Emory University developed HomePal, a passive home sensing system that monitors movement, screen time, sleep, phone usage and vocal patterns to detect behavioral signatures of loneliness in older adults. The system uses commercially available sensors and reports results to a caregiving team. Extends ambient home health monitoring from physical safety to mental health and social wellbeing.",src:"VCU College of Engineering",url:"https://blogs.vcu.edu/engineering/2026/11/02/vcu-developed-home-sensor-system-could-spot-loneliness-in-older-adults/",new:true},
  {date:"2026-10-26",cat:"Regulatory",title:"When AI Becomes a Medical Device: FDA Boundaries for Patient-Facing Health Tools",desc:"Legal analysis published in Citeline examines how the FDA evaluates AI health software based on intended use and functionality, explaining how to design AI features that preserve clinicians' independent judgment and support exclusion from device regulation. The analysis addresses the regulatory boundary question that every consumer health AI vendor faces: when does a wellness feature become a medical claim that triggers FDA oversight?",src:"Citeline",url:"https://insights.citeline.com/medtech-insight/perspectives/when-ai-becomes-a-medical-device-fda-boundaries-for-patient-facing-health-tools-QICAHCWLUJADBGL6C47I6LJ5ZQ/",new:true},
  {date:"2026-09-30",cat:"Product",title:"Welldoc Launches AI-Powered Care Loop Connecting Daily Health to Care Teams",desc:"Welldoc launched an AI-powered care loop built on closed Small Language Models (SLMs) that delivers personalized guidance between visits, backed by 11 FDA clearances, 69 patents, and 100+ peer-reviewed clinical publications. The platform connects daily health data to care teams while keeping patients and clinicians in control. Represents the clinical-grade, regulated approach to consumer health AI, distinct from the unregulated wellness coaching market. Vendor claim: clinical-grade AI platform, FDA-cleared.",src:"Welldoc",url:"https://www.welldoc.com/news/welldoc-launches-ai-powered-care-loop-connecting-daily-health-to-care-teams-keeping-patients-and-clinicians-in-control"},
  {date:"2026-09-30",cat:"Product",title:"Joined Bio Introduces Nova, an AI Assistant for Research Participants' Own Health Records",desc:"Joined Bio launched Nova, an AI assistant that lets research participants ask questions about their Complete Health Record in plain language. Participants can ask anything from 'Give me a summary of my health' to 'How is my heart rate trending?' to 'When was my last tetanus vaccine?' and get answers drawn from their own records. Joined Bio also introduced document uploads to build out the Complete Health Record. Represents the extension of personal health AI into the research-participant context, where understanding one's own health data drives engagement and data quality. Vendor claim: helps participants understand health information, not a substitute for healthcare providers.",src:"Joined Bio",url:"https://joined.bio/news/joined-bio-introduces-nova-ai-assistant/"},
  {date:"2026-09-10",cat:"Product",title:"Dimer Health Launches AiME, a Personalised AI Health Agent for Post-Discharge Care",desc:"Dimer Health launched AiME, a personalised AI-powered health agent that patients access from home after discharge. AiME pairs AI-driven guidance with a 24/7 clinical team, acting as a care navigator that helps patients decide whether what they feel is normal or an emergency. The product addresses the gap between hospital monitoring and home recovery, where patients lose the 'call button' they had in the hospital. Vendor claim: personalised AI-driven guidance with clinical backup, not a replacement for emergency care.",src:"PR Newswire",url:"https://www.prnewswire.com/news-releases/dimer-health-brings-the-hospital-call-button-home-with-aime-302872914.html"},
  {date:"2026-08-21",cat:"Trend",title:"AI Health Coaches Compared: Four Wearable Platforms, Four Price Points",desc:"A market comparison found four wearable platforms selling AI health coaches in 2026: Google Health Coach at $9.99/month, WHOOP Coach included in memberships from $199/year, Oura Advisor included at $5.99/month, and Garmin Active Intelligence at $6.99/month. Apple still has no AI coach. The analysis frames the competitive shift: in 2024 the pitch was more sensors, in 2026 it is a chatbot that reads them for you. Every major wearable platform now sells an AI coach that ingests sleep, strain and heart data and tells users what to do about it.",src:"SmartBodyTouch",url:"https://smartbodytouch.com/ai-health-coach-wearables-compared/"},
  {date:"2026-08-15",cat:"Product",title:"WHOOP Adds On-Demand Clinician Video Visits and 'My Memory' AI Context to Coaching",desc:"WHOOP announced on-demand video consultations with licensed clinicians alongside new AI coaching features including 'My Memory,' a personal-context hub that lets the AI coach remember a user's real-life context, and proactive check-ins that adjust training or sleep recommendations based on life events. The move pits WHOOP directly against Oura's AI health assistant and represents wearable makers shifting from biometric tracking to integrated health services combining AI coaching with human clinical care.",src:"AI Data News",url:"https://www.aidatanews.com/whoop-will-now-let-its-ai-coach-remember-your-life-story-and-put-a-real-doctor-on-video-call/"},
  {date:"2026-10-31",cat:"Product",title:"HealthPulse: AI Health Coach Enters TestFlight Beta with Apple Health Integration",desc:"A third-party app called HealthPulse entered TestFlight beta, offering daily Sleep, Recovery and Exertion scores, trends, sleep and workout insights by exploring Apple Health data. The beta includes optional meal logging, lab report summaries, cycle insights, and Velo AI briefings and questions. Demonstrates the emerging third-party Apple Health AI coach ecosystem enabled by Apple's Health data APIs. Vendor claim: wellness insights, not a medical device.",src:"Apple TestFlight",url:"https://testflight.apple.com/join/W6DWpe9D",new:true},
  {date:"2026-10-29",cat:"Regulatory",title:"California Extends CMIA Privacy Protections to Consumer Health Care Chatbots",desc:"California enacted AB 1979, extending the Confidentiality of Medical Information Act (CMIA) to businesses offering consumer-facing health care chatbots. Starting January 1, 2027, companies providing chatbots for managing health information or for diagnosis, treatment or management of a medical condition will be deemed health care providers under CMIA, required to maintain the same confidentiality standards as providers. The law also limits how health care providers may use AI in clinical care. Represents the first state law to explicitly bring consumer health AI chatbots under medical privacy protections equivalent to those covering providers.",src:"Hunton Andrews Kurth",url:"https://www.hunton.com/privacy-and-cybersecurity-law-blog/california-law-extends-cmia-protections-to-health-care-chatbots-and-enacts-new-guardrails-on-ai-use-in-clinical-care",new:true},
  {date:"2026-10-20",cat:"Product",title:"UniqueHuman Launches Niq, a Proactive AI Health Agent for Migraine",desc:"UniqueHuman introduced Niq, a proactive health agent from a startup founded by former Apple Watch team member Praneeta Pujari. Niq starts with migraine: it learns the user's baseline from wearables, health records and self-reported logs, warns about flare-ups, and assists with follow-up care. The iPhone app is free to use. Represents a shift from general-purpose health agents to condition-specific proactive agents for chronic conditions. Vendor claim: proactive health management, not a medical device.",src:"Agent Playbox",url:"https://agentplaybox.com/news/uniquehuman-launches-niq-health-agent/"},
  {date:"2026-10-01",cat:"Research",title:"BMJ Health & Care Informatics: Systematic Review of Patient Safety and Health Equity in AI Triage Tools",desc:"A systematic review published in BMJ Health & Care Informatics synthesised real-world patient safety evidence for AI-enabled triage tools in primary care and mapped whether safety has been examined across sociodemographic groups. The review searched PubMed, Embase, Web of Science and Scopus (January 2015-November 2025) with citation searching, covering prospective studies evaluating AI triage tools in real-world primary care settings. Addresses the gap between vignette-based validation and real-world safety evidence, and whether equity across sociodemographic groups has been assessed.",src:"BMJ Health & Care Informatics",url:"https://doi.org/10.1136/bmjhci-2026-102427"},
  {date:"2026-10-01",cat:"Product",title:"Guardian Pocket: A-LIST Ships a Local-First Health Agent Where You Own the Data",desc:"A-LIST launched Guardian Pocket, billed as the world's first local health agent where the user owns the data end to end. Data never leaves the phone, the agent is as capable as expensive frontier agents at its tasks, and it runs fast by fusing model and harness into one integrated system. The release is part of A-LIST's broader shift to a free, no-account, privacy-first model. Represents the local-first, privacy-maximalist design pattern in consumer health AI. Vendor claim: 100% private, on-device health agent.",src:"A-LIST Blog",url:"https://a-list.com/blog/building-guardian-pocket"},
  {date:"2026-09-02",cat:"Product",title:"Everlab Launches Concierge, an AI Health Assistant Grounded in Members' Own Health Data (Australia)",desc:"Australian preventative health company Everlab launched Concierge, an in-app AI health assistant grounded in each member's own health record, with access to Everlab clinicians when needed. The assistant uses the member's diagnostic data, health history and existing care plan as context, addressing the limitation that general-purpose AI lacks individual health context. The launch signals international expansion of the personal health agent concept beyond the US. Vendor claim: AI health assistant grounded in personal health data, not a replacement for clinical care.",src:"Everlab",url:"https://www.everlab.com.au/press/everlab-launches-concierge-an-ai-health-assistant-grounded-in-members-own-health-data"},
  {date:"2026-10-29",cat:"Product",title:"Ro Launches 'Robin' AI Health Agent for Telehealth Subscribers",desc:"Telehealth company Ro launched an AI health agent named Robin that uses doctor notes, patient feedback, prescriptions and Apple Health data already stored in the Ro app to personalise recommendations for medication changes, dosing tweaks and habit improvements. Robin can draft a note to a doctor suggesting a medication change. CEO Zach Reitano positioned Ro as a 'quarterback' for the entire American healthcare system, expanding in-house care concentrically. Brown University's Dr Ateev Mehrotra flagged the need for evidence before millions of Americans adopt it and noted financial-incentive concerns unique to commercial telehealth. Vendor claim: AI-powered personalised health recommendations, not a substitute for medical care.",src:"Business Insider",url:"https://www.businessinsider.com/exclusive-ro-launches-ai-agent-for-healthcare-2026-10",new:true},
  {date:"2026-10-27",cat:"Product",title:"Apple iOS 27.2 Final Ships Without AI-Powered Health App",desc:"iOS 27.2 has rolled out to iPhones without the redesigned AI-powered Health app, which was tested in betas for weeks then quietly removed in the fourth beta on October 13. The final update ships with the current Health app restored. The AI-powered version, featuring health summaries, an Insights tab, Health Age score and fitness checks, is now expected later. This marks the second postponement of Apple's Apple Intelligence-powered health insights overhaul, following Bloomberg's report that the fuller AI health coach (Project Mulberry) was scaled back in February.",src:"Gizbot / MacRumors",url:"https://www.gizbot.com/news/apple-has-been-building-an-ai-health-coach-since-2025-129449.html",new:true},
  {date:"2026-10-28",cat:"Regulatory",title:"24 States Now Have Comprehensive Consumer Privacy Laws as Sensitive-Data Sales Bans Spread",desc:"Four new states (Alabama, Louisiana, Oklahoma, Vermont) enacted comprehensive consumer privacy laws in 2026, bringing the total to 24. The defining trend is a shift beyond consent to outright bans on selling sensitive data: New Jersey prohibits selling sensitive data regardless of consumer consent, Connecticut and Virginia ban sales of precise geolocation, and Delaware expanded its sensitive-data definition to include neural data and inferences revealing health conditions. Colorado's revised AI law will regulate automated technology in consequential decisions starting Jan 1, 2027. Data broker registration expanded to Connecticut and New Jersey. Massachusetts is considering a private right of action.",src:"MultiState",url:"https://www.multistate.us/insider/2026/10/28/twenty-four-states-now-have-comprehensive-consumer-privacy-laws",new:true},
  {date:"2026-10-26",cat:"Research",title:"Separating Safety from Preference in Clinical LLM Evaluation: mRehab Advisory Agent",desc:"A human-centered evaluation of the mRehab Advisory Agent with two cohorts: six domain experts rating clinical safety and correctness, and three end users rating helpfulness, affect, and clarity. Experts ranked the agent first most often (53.3%, p<0.001), yet it led on affect and clarity, not helpfulness, and drew mixed safety verdicts - demonstrating that a fluent, well-liked answer can still be clinically unsafe, and that preference-only evaluation hides this by collapsing many judgments into one winner. Published at the 4th International Workshop on Human-Centered Sensing, Modeling, and Intelligent Systems.",src:"ACM",url:"http://dl.acm.org/doi/10.1145/3842436.3843811",new:true},
  {date:"2026-10-26",cat:"Product",title:"Microsoft Copilot Health Temporarily Unavailable After Unified Copilot Update",desc:"Microsoft's October 26 unified Copilot app update removed Copilot Health from all platforms. The Health section displays 'Coming soon' on web, Windows, Edge, and iOS. Microsoft confirmed the disruption is temporary during the unified Copilot transition, with wearable connections expected to return later than core health features. Users who had connected Garmin data via Apple Health report losing access. Requires Microsoft 365 Personal, Family, or Premium subscription.",src:"Microsoft Q&A / Reddit",url:"https://learn.microsoft.com/en-us/answers/questions/6051800/copilot-health",new:true},
  {date:"2026-10-26",cat:"Product",title:"RingConn Partner Officially Launches AI Wellness Companion",desc:"RingConn launched Partner, an AI wellness companion built into its smart ring platform, following a beta testing phase. Partner connects wearable sensor data with conversational AI to deliver personalised health guidance, supports custom naming, and integrates additional health data sources beyond the ring's own metrics. Free to use with optional value-added services. Vendor claim: AI-powered wellness companion, not a medical device.",src:"RingConn",url:"https://ringconn.com/blogs/news/ringconn-partner-now-officially-launching",new:true},
  {date:"2026-10-23",cat:"Product",title:"Alloop Launches Trio: Modular 3-in-1 Wearable Built Around a Personal AI Health Agent",desc:"Alloop unveiled a modular health wearable with one interchangeable sensing core (the Cube) that snaps between a smart ring and a wristband, plus a Halo module for voice interaction with its AI Health Agent. The open platform integrates Apple Health, Google Health and Health Connect, and the agent interprets physiological data alongside user-journalled meals, activities and symptoms. A Bio Age score spans six domains: sleep, activity, nutrition, cardiovascular, metabolic and musculoskeletal. Launching on Kickstarter.",src:"OpenPR / Alloop",url:"https://www.openpr.com/news/4671109/alloop-officially-launches-trio-a-modular-3-in-1-wearable"},
  {date:"2026-10-21",cat:"Product",title:"Biblo Launches Personal AI Fitness Agent for iMessage",desc:"Biblo introduced a personal AI fitness agent that users can text via iMessage. Users send a photo of food or describe what they ate, and Biblo estimates calories and macros. The basic service is free on iPhone with no separate download required. Represents the lightweight, messaging-native design pattern for consumer health AI, lowering friction by meeting users in existing chat interfaces rather than requiring a dedicated app. Vendor claim: fitness and nutrition tracking, not a medical device.",src:"Biblo",url:"https://www.heybiblo.com/blog/introducing-biblo"},
  {date:"2026-10-21",cat:"Research",title:"Nature Publishes 'The Anatomy of a Personal Health Agent'",desc:"Google Research published the most comprehensive evaluation of a consumer health agent to date. The open-source multi-agent framework serves four user journeys - general health knowledge, personal data interpretation, wellness advice and symptom assessment - through three specialist sub-agents: a data science agent that analyses longitudinal wearable and medical data against population statistics, a health domain expert agent that combines personal context with health knowledge, and a health coach agent that handles multi-turn interaction, goal setting and progress tracking. Evaluated across 11 benchmark tasks with more than 7,000 annotations and about 1,350 hours of work from health experts and end users. Independent coverage reported safety gaps in a meaningful share of generated summaries.",src:"Nature",url:"https://www.nature.com/articles/s41586-026-11161-8"},
  {date:"2026-10-21",cat:"Research",title:"Google Research Blog: Anatomy of a Personal Health Agent",desc:"Google Research published a companion explainer describing the personal health agent architecture and its grounding in the WEAR-ME metabolic health study (n=1,165) for real-world validity. Positions the work as a basis for further research on personal health agents for daily health and well-being.",src:"Google Research",url:"https://research.google/blog/the-anatomy-of-a-personal-health-agent/"},
  {date:"2026-10-21",cat:"Research",title:"Nature Editorial: Using AI to Offer Personalised Health Advice",desc:"Nature ran a companion editorial placing the personal health agent paper in context, citing Pew survey data on health information and trust, and prior work on AI health advice. Signals that mainstream scientific publishing now treats consumer health agents as a serious research area rather than a product category.",src:"Nature",url:"https://www.nature.com/articles/d41586-026-03065-4"},
  {date:"2026-10-21",cat:"Research",title:"Google Health Agent Tops Gemini but Shows Safety Gaps",desc:"Independent analysis of the Nature paper reported that the Personal Health Agent outperformed its base Gemini models on personal health tasks but still showed safety gaps in roughly 17% of summaries. The system runs on Gemini 2.0 models with an orchestrator coordinating the three specialist agents.",src:"Becker's Hospital Review",url:"https://www.beckershospitalreview.com/healthcare-information-technology/innovation/googles-health-ai-agent-tops-gemini-but-carries-safety-gaps-7-things-to-know/"},
  {date:"2026-10-14",cat:"Research",title:"BeST Benchmark: Self-Triage Systems vs OpenAI Models Across Multiple Generations",desc:"The Central Research Institute of Ambulatory Health Care in Germany (Zi) published BeST (Benchmark Self-Triage), comparing emergency recognition and overall agreement with clinical judgement across self-triage systems and multiple generations of OpenAI models against preliminary expert consensus. The study addresses how triage outcomes differ across GPT model generations, providing quality assurance data for digital self-triage as adoption widens. Preprint, not yet peer-reviewed.",src:"medRxiv (BeST Study Group)",url:"https://www.medrxiv.org/content/medrxiv/early/2026/10/14/2026.10.12.26365287.full.pdf"},
  {date:"2026-10-13",cat:"Product",title:"Apple Pulls AI-Powered Health App from iOS 27.2 Beta - Second Delay for Apple Intelligence Health",desc:"Apple removed its redesigned Health app from iOS 27.2 beta 4, marking the second postponement of the Apple Intelligence-powered health insights overhaul. The app was originally previewed in September with features including an Insights tab, personalised guidance, readiness score, and Health Age calculation. Bloomberg had reported Apple scaled back the fuller AI health coach (Project Mulberry) in February. The current Health app was restored to iOS 27.2 in the latest beta, with the AI-powered version now expected later.",src:"Stuff / 9to5Mac",url:"https://www.stuff.tv/news/apple-health-app-pulled-from-ios-27-2-beta-heres-the-new-timeline-for-the-ai-powered-health-insights/"},
  {date:"2026-10-12",cat:"Product",title:"Google Launches Fitbit Edge with AI Health Guardian",desc:"Google announced the Fitbit Edge, a $179.99 fitness tracker with 7-day battery, GPS, automatic workout recognition and a new Health Guardian suite that passively tracks blood pressure trends and insulin resistance trends from sensor data - no cuff, no blood sample. Health Guardian rolls out to Fitbit Air and Fitbit Edge for Google Health Premium subscribers ($9.99/mo or $99.99/yr), with monthly reports and Health Coach guidance on lifestyle adjustments. Pre-orders opened immediately; retail availability starts Oct 27. Vendor claim: general wellness, not intended to diagnose or treat.",src:"Google",url:"https://blog.google/products-and-platforms/devices/fitbit/google-fitbit-edge/"},
  {date:"2026-10-12",cat:"Product",title:"Google Health App Adds Lab Results, CGM Data and Meal Logs",desc:"Google opened the Google Health app to Function Health lab results, Abbott Lingo continuous glucose monitor readings and MyFitnessPal meal logs, with Flo cycle data to follow in early 2027. The same update deepened Apple Health integration and improved Coach memory. The Fitbit app became the Google Health app in May 2026, consolidating Google's consumer health stack: wearable hardware, health data aggregation and AI coaching in one platform.",src:"Google",url:"https://blog.google/products-and-platforms/products/google-health/fitbit-google-health-updates/"},
  {date:"2026-10-12",cat:"Product",title:"Google Health Partners with Flo Health for Women's Health Coaching",desc:"Google announced a partnership with Flo Health (80M+ monthly users) to integrate cycle data with the Google Health app and Health Coach. Flo users will sync cycle data with Google Health metrics like resting heart rate and sleep stages, with Google Health Premium delivering tailored coaching across cycle, sleep and recovery. The companies plan joint research into underserved topics including perimenopause, pregnancy and postpartum recovery. Vendor claim: general wellness, not diagnosis.",src:"Google / PYMNTS",url:"https://blog.google/products-and-platforms/products/google-health/commitment-womens-health-flo-health-partnership/"},
  {date:"2026-10-08",cat:"Research",title:"Sex-Based Diagnostic Bias Found in AI Symptom Checkers",desc:"A peer-reviewed audit of three AI symptom checkers (Ada Health, Isabel Healthcare, Docus AI) across four clinical vignettes found sex-based divergence in differential diagnosis rank, probability estimates and advisory text. Isabel Healthcare ranked Heart Attack first for the male profile but third for the female profile on ACS with chest pressure. Docus AI described immediate medical attention as crucial for the male profile but merely important for the female profile on identical symptoms. The direction of divergence was not uniform, but findings support equity auditing of both numerical outputs and generated explanatory text.",src:"Frontiers in Digital Health",url:"https://www.frontiersin.org/journals/digital-health/articles/10.3389/fdgth.2026.1950777/full"},
  {date:"2026-10-08",cat:"Research",title:"Nottingham Trent University: Privacy-Preserving Ambient Home Monitoring via Radar-Thermal Sensing",desc:"NTU researchers published a system in Sensors that combines mmWave radar, low-resolution thermal sensors and smart plugs to track daily routines and detect health emergencies without cameras or wearables. AI learns individual behaviour patterns to flag anomalies such as falls, prolonged inactivity or altered sleep. Tested in mock domestic environments with six room layouts. The privacy-by-design approach uses pixelated thermal sensors that identify posture without facial features, and smart-plug appliance patterns to infer daily activities. The authors position it as an ambient assisted living environment for ageing in place.",src:"News-Medical.net / Sensors",url:"https://www.news-medical.net/news/20261008/AI-powered-home-monitoring-tracks-older-adultse28099-health-while-protecting-privacy.aspx"},
  {date:"2026-10-05",cat:"Research",title:"Nature Health: Respiratory Assessment Chatbot Validated in Nationwide Messaging System",desc:"A randomised preregistered study published in Nature Health evaluated a respiratory assessment chatbot embedded in a nationwide messaging system for layperson diagnosis and triage. The study tested diagnostic and triage accuracy across respiratory symptoms in a real-world messaging deployment, providing evidence for chatbot-assisted respiratory self-assessment at population scale.",src:"Nature Health",url:"https://www.nature.com/articles/s44360-026-00189-9"},
  {date:"2026-10-01",cat:"Research",title:"Multi-Agent LLM Framework for Personalised Health Checkup Interpretation and Guidance",desc:"arXiv preprint presenting a multi-agent LLM system that identifies multiple intents in health checkup questions, maps each to a task-specific agent, executes them in parallel, and synthesises results. The authors compared single-agent and multi-agent configurations, finding the multi-agent approach improved answer quality for complex health checkup interpretation requiring reasoning across longitudinal records, medical knowledge, lifestyle guidance and healthcare navigation.",src:"arXiv",url:"https://arxiv.org/abs/2610.01451"},
  {date:"2026-09-30",cat:"Research",title:"JMIR: Smart Home Technology-Enhanced Health Care - Scoping Review of Sensors, Applications and Integration",desc:"A scoping review published in JMIR Medical Informatics synthesised literature on technology-enhanced health care (TEH) integration within smart homes, examining global deployment patterns, technological maturity, biomedical sensor integration, machine learning applications, and health outcomes. The review covers the Internet of Medical Things, wearable biosensors and AI-driven analytics for proactive care delivery, particularly for older adults and individuals with chronic conditions living independently.",src:"JMIR Medical Informatics",url:"https://medinform.jmir.org/2026/1/e89189/"},
  {date:"2026-09-25",cat:"Research",title:"PIA: Personal Intelligence Agent Turns Health Conversations into Records and Records into Understanding",desc:"arXiv preprint introducing PIA, a personal intelligence agent that transforms health conversations into structured records and uses those records for longitudinal understanding. Unlike general-purpose agent memory that summarises conversations into text snippets, PIA extracts structured health data (doses, trends, timelines) and retrieves by structured query rather than text similarity. The authors argue a health agent cannot run on summaries alone: a dose becomes a sentence, temporal references resolve at model discretion, and glucose trends cannot be answered by text similarity.",src:"arXiv",url:"https://arxiv.org/abs/2609.31255"},
  {date:"2026-09-22",cat:"Research",title:"Nature Digital Medicine: Patient Journey Evaluation for Consumer AI Health Assistants",desc:"A Perspective published in Nature Digital Medicine defines a journey-level evaluation and governance framework for record-linked patient education by consumer AI health assistants. The authors introduce the personal health workspace (PHW), a user-controlled setting for evaluating an assistant as a stateful system across a patient journey rather than isolated Q&A turns. The framework includes a clinical journey map and an auditable interaction loop for testing longitudinal reliability before deployment and monitoring afterward.",src:"Nature Digital Medicine",url:"https://doi.org/10.1038/s41746-026-03251-8"},
  {date:"2026-09-14",cat:"Research",title:"SAFE-CARE Bench: Safety Benchmark for Multi-Turn Healthcare AI Agent Conversations",desc:"SAFE-CARE Bench is a benchmark specification and evaluation protocol testing what a healthcare AI agent does across a conversation, where risk builds turn by turn and a missed escalation is the failure that matters most. A controlled A0 - A4 ablation runs five agent variants over identical simulated conversations, with model, temperature and seed held constant. Each tier declares capability flags explicitly so any two tiers diff mechanically and every score change is attributable to a named capability bundle: grounding, safety guardrails, personalisation or agency.",src:"Zenodo",url:"https://doi.org/10.5281/zenodo.22739092"},
  {date:"2026-09-02",cat:"Research",title:"Are Frontier LLMs Safer Than Government-Backed Symptom Checkers for Clinical Self-Triage?",desc:"A standardised vignette evaluation published on medRxiv compared Australia's Healthdirect symptom checker (2.4 million uses in FY2024-25) against six LLM configurations across triage accuracy and safety. The study is the first to evaluate a government-backed symptom checker against frontier large language models, and explores whether premium LLM subscriptions improve triage safety. Preprint, not yet peer-reviewed.",src:"medRxiv",url:"https://doi.org/10.64898/2026.09.01.26361908"},
  {date:"2026-09-02",cat:"Research",title:"AI Triage Concordance Varies by User Authentication Status in US Health System",desc:"A prospective cohort analysis published in npj Health Systems examined 6,772 care seekers using an AI triage tool at a US health system. The study found that users' pre-stated care intent aligned with AI recommendations differently depending on authentication status, and that alignment shaped downstream engagement. The findings address how user identity and stated intent affect the reliability of AI triage tools deployed at the digital front door of health systems.",src:"npj Health Systems",url:"https://www.nature.com/articles/s44401-026-00140-w"},
  {date:"2026-08-11",cat:"Product",title:"Abbott and Google Partner on AI-Powered Metabolic Insights",desc:"Abbott and Google announced a partnership pairing the Lingo consumer CGM with Google Health's AI to deliver personalised metabolic insights through the Google Health app. Lingo users can view glucose trends alongside other health metrics, with Google's Health Coach translating patterns into nutrition, activity and sleep recommendations. The companies also plan one of the largest real-world metabolic health studies, integrating CGM, wearable, lab and survey data to examine connections between daily behaviour and metabolic health, including early identification of prediabetes.",src:"Fierce Biotech / Abbott",url:"https://www.fiercebiotech.com/medtech/abbott-teams-google-health-ai-powered-health-trends-app"},
  {date:"2026-07-22",cat:"Product",title:"Samsung Rolls Out Beta of AI-Powered Health Assistant in Samsung Health App",desc:"Samsung launched a beta version of its AI-powered personal health assistant embedded in the Samsung Health app, available to eligible US users. The assistant answers health questions and provides personalised guidance and recommendations based on Samsung Health data. Planned future capabilities include coaching to help users achieve health goals. Samsung's entry adds a major Android device maker to the consumer health AI agent landscape alongside Google, Apple and the wearable specialists.",src:"Fierce Healthcare",url:"https://www.fiercehealthcare.com/ai-and-machine-learning/samsung-launches-beta-version-ai-powered-health-assistant-across-us"},
  {date:"2026-06-18",cat:"Product",title:"MedPal AI Launches Juno, an Agentic AI Health Companion Powered by Anthropic Claude",desc:"MedPal AI launched Juno, its next-generation agentic AI health companion, moving from responsive AI to agentic AI powered by Anthropic's latest Claude models and DigitalOcean. Juno works on the patient's behalf rather than just answering when asked, representing the shift from conversational to agentic AI in consumer health. Vendor claim: agentic AI health companion, not a medical device.",src:"FT.com / MedPal AI",url:"https://markets.ft.com/data/announce/full?dockey=1323-17645095-2ELGELJ3D2E3H6KL9DB13CAEB5"},
  {date:"2026-06-29",cat:"Regulatory",title:"Vermont Enacts VDPOSA with Standalone Consumer Health Data Provisions and AI Transparency Requirements",desc:"Vermont's Data Privacy and Online Surveillance Act (VDPOSA) takes effect January 1, 2028, with standalone consumer health data provisions that apply regardless of general applicability thresholds. The law prohibits geofencing within 1,850 feet of healthcare facilities, requires consent before selling consumer health data, and includes AI transparency requirements for controllers. Extends the trend of states creating health-specific privacy obligations outside HIPAA.",src:"Bass, Berry & Sims",url:"https://bassberry.com/news/vermonts-consumer-data-privacy-law-joins-the-national-wave/"},
  {date:"2026-06-16",cat:"Research",title:"Nature Health: AI Symptom Checker Integrated into MomConnect Maternal Healthcare Platform",desc:"A prospective observational mixed-methods study published in Nature Health evaluated an AI-based symptom checker integrated into South Africa's MomConnect maternal healthcare platform. The study examined the symptom checker's integration, usage patterns and performance within a national digital health messaging system for maternal health, providing real-world evidence for AI symptom assessment in a public health context at national scale.",src:"Nature Health",url:"https://www.nature.com/articles/s44360-026-00125-x"},
  {date:"2026-05-26",cat:"Regulatory",title:"States Accelerate Health AI Legislation in 2026: Insurer, Provider and Chatbot Rules",desc:"Holland & Knight's review of 2026 state legislation found states leading Congress on health AI governance: Alabama, Indiana, Utah, Washington, Maryland and Georgia enacted laws requiring human oversight of AI in insurer prior-authorisation decisions; Maine and Arizona restricted autonomous clinical decision-making in behavioural health; Idaho, Nebraska, Oregon and Tennessee passed AI companion and chatbot safety acts requiring disclosure, crisis-response protocols and prohibiting chatbots from representing themselves as licensed mental health professionals. Utah piloted a regulatory sandbox for AI-enabled prescription renewal.",src:"Holland & Knight",url:"https://www.hklaw.com/en/insights/publications/2026/05/states-continue-efforts-to-regulate-ai-in-healthcare"},
  {date:"2026-04-30",cat:"Regulatory",title:"Consumer Health Data Privacy Patchwork Growing as Federal Enforcement Pulls Back",desc:"Healthcare Dive reported that the federal government has stepped back from HIPAA enforcement just as state legislatures accelerated privacy efforts, making compliance more fragmented. Connecticut, Maryland, Nevada and Washington enacted consumer health data privacy laws requiring consent before disclosing health data. Experts said patients are voluntarily entering sensitive health information into consumer AI tools like ChatGPT without understanding the risks, and no comprehensive federal solution is on the horizon.",src:"Healthcare Dive",url:"https://www.healthcaredive.com/news/consumer-health-data-privacy-regulatory-patchwork-state-laws/818852/"},
  {date:"2026-04-15",cat:"Trend",title:"IAPP: Five Health AI Agents Launched in Three Months - Privacy Gaps Documented",desc:"A comparative analysis by Théodore Christakis (University of Grenoble Alpes) found five companies launched health-specific AI products between January and March 2026: OpenAI ChatGPT Health (7 Jan), Anthropic Claude for Healthcare (11 Jan), Amazon Health AI (22 Jan), Microsoft Copilot Health (12 Mar) and Perplexity Health (19 Mar). All follow a similar model - EHR integration via intermediaries, wearable connections, no-training commitments, US-only availability. None meets the full 'sealed mode' privacy standard; none is HIPAA-covered; all exclude European users. OpenAI reports 230 million people ask ChatGPT health questions weekly.",src:"IAPP",url:"https://iapp.org/news/a/the-health-ai-agent-rush-five-products-in-three-months-and-the-privacy-questions-that-got-left-behind"},
  {date:"2026-03-19",cat:"Product",title:"Perplexity Launches Perplexity Health with EHR, Wearables and Health Advisory Board",desc:"Perplexity unveiled Perplexity Health on 19 March 2026, rolling out to US Pro and Max subscribers through April. The platform connects 1.7M+ providers via b.well, integrates Apple Health, Fitbit, Ultrahuman, Withings and Clue via Terra API, and offers AI agents for nutrition, sleep and visit prep built on Perplexity Computer. A Health Advisory Board including Dr Eric Topol was announced. Perplexity commits to no training on health data and citations on every response.",src:"Perplexity",url:"https://perplexityaimagazine.com/ai-news/perplexity-health-launch/"},
  {date:"2026-09-24",cat:"Product",title:"Google Health Guardian Features Go Live for Pixel Watch Users",desc:"Google announced that Health Guardian features - blood pressure trends, insulin resistance trends and sleep breathing quality - are rolling out in the Google Health app for Pixel Watch 3, 4 and 5 users, with first trend reports arriving in early October. Breathing Emergency Detection for Pixel Watch 4 and 5 launched in select European countries. Fitbit Air users get insulin resistance and blood pressure trends with Google Health Premium later in the year. Vendor claim: general wellness, not diagnosis.",src:"Google",url:"https://blog.google/products-and-platforms/products/google-health/health-guardian-features-live/"},
  {date:"2026-09-15",cat:"Product",title:"Apple Extends Apple Intelligence into the Health App",desc:"Apple announced health and fitness capabilities powered by Apple Intelligence with iOS 27 and iPadOS 27. The Health app is positioned as the central, secure location for a user's health and fitness information, with on-device processing and expanded interpretation of long-term metrics rather than simple daily logging. Apple had previously scaled back its fuller AI health coach effort, and Bloomberg reported the paid Health+ service was still planned for 2026.",src:"Apple Newsroom",url:"https://www.apple.com/newsroom/2026/09/apple-advances-health-and-fitness-capabilities-using-apple-intelligence/"},
  {date:"2026-09-08",cat:"Product",title:"Meta Launches Muse Personal AI Agent with Health and Fitness App Connections",desc:"Meta introduced Muse, a general-purpose personal AI agent that connects to users' apps and services including health and fitness, email, calendars and payments. Powered by Meta's Muse Spark model, it runs in a dedicated Muse Secure VM with a separate Sentinel safety agent. Available via web, iOS, Android and WhatsApp, with Meta AI glasses support coming. Free tier with Power ($20/mo) and Maximum ($100/mo) plans. Meta claims Muse does not share conversations with its ads systems. Launch came two weeks after Meta's $18B settlement over social media harms, raising trust questions for a company now seeking access to health data. Vendor claim: secure personal AI agent, not health-specific.",src:"TechCrunch",url:"https://techcrunch.com/2026/09/08/meta-debuts-its-muse-ai-agent-will-consumers-trust-it/"},
  {date:"2026-08-20",cat:"Research",title:"AI Symptom Checkers and Patient Care-Seeking Behaviour",desc:"Coverage of health-system deployments found that AI-powered symptom checkers do direct worried patients to care. From roughly 22,000 digital triage sessions at Mount Sinai, about 80% of users who started a session completed the conversation.",src:"Association of Health Care Journalists",url:"https://healthjournalism.org/blog/2026/08/ai-powered-symptom-checkers/"},
  {date:"2026-08-19",cat:"Research",title:"Verily's Personal Health Assistant Misses Undertriage Targets in Predeployment Validation",desc:"Verily Health analytically validated its LLM-based Personal Health Assistant (PHA) using 772 synthetic cases reviewed by 5 independent physicians against published telephone-triage protocols. PHA met the overtriage criterion (11.0%, criterion <30%) but missed both undertriage criteria: urgent undertriage 6.9% (criterion <5%) and nonurgent undertriage 18.4% (criterion <15%). Undertriage was identified as the principal performance gap requiring product refinement. PHA was based on GPT-5.4-mini. Published in JMIR Formative Research.",src:"JMIR Formative Research",url:"https://doi.org/10.2196/103419"},
  {date:"2026-07-23",cat:"Product",title:"OpenAI Launches 'Health in ChatGPT' with Records and Apple Health",desc:"OpenAI rolled out Health in ChatGPT to Free, Go, Plus and Pro users in the United States, letting eligible users securely connect medical records and Apple Health data so the assistant can interpret information in context, track changes and hold more personalised conversations. Coverage highlighted that once health data leaves a provider, HIPAA no longer protects it - making the consumer data-governance question central. The same period saw OpenAI connect ChatGPT to Epic records for clinicians.",src:"OpenAI / Paubox",url:"https://www.paubox.com/blog/chatgpt-health-launches-nationwide-but-medical-records-not-hipaa-protected"},
  {date:"2026-07-15",cat:"Research",title:"HealthClaw: Open-Source Agent for Longitudinal Personal Health Management",desc:"arXiv preprint introducing HealthClaw, an open-source agent architecture that separates shared safety rules and medical knowledge from private longitudinal memory (profile facts, reusable procedures, episodic traces). After each interaction, an induction step decides what to retain, revise, or discard. Across 900 longitudinal support probes, answer accuracy rose from 0.2% with current-query prompting to 45.7% with HealthClaw, while context exposure was 71.7% lower than full-history prompting. In 100 privacy probes, HealthClaw produced fewer unsafe disclosures than both baselines. Code is publicly available on GitHub.",src:"arXiv",url:"https://arxiv.org/abs/2607.13940"},
  {date:"2026-07-10",cat:"Research",title:"Google's SensorFM Points Wearables Toward AI Health Agents",desc:"Forbes reported on Google's SensorFM, trained on approximately a trillion minutes of wearable data, and framed the shift from raw metrics to AI health agents - a trend already reshaping WHOOP and Oura, which were both adding two-way coaching dialogue on top of one-way insight feeds.",src:"Forbes",url:"https://www.forbes.com/sites/josipamajic/2026/07/10/googles-sensorfm-reveals-where-ai-takes-wearable-health/"},
  {date:"2026-06-28",cat:"Trend",title:"The Rise of Ambient Home Health Monitoring",desc:"Forbes documented the shift toward non-contact sensing - mmWave radar, WiFi sensing, acoustic AI, smart glasses - as a way to monitor vitals and activity at home without adding another wearable. Privacy-first, local-first processing emerged as the design pattern, with vendors arguing that sensing must blend into form factors people already use.",src:"Forbes",url:"https://www.forbes.com/sites/saibala/2026/06/28/a-doctor-at-home-the-rise-of-ambient-home-health-monitoring/"},
  {date:"2026-05-29",cat:"Product",title:"Microsoft Copilot Health Enters Preview",desc:"Microsoft opened Copilot Health in preview after its March launch. The product aggregates personal health records, wearable data from Apple Health and Fitbit, and laboratory results inside a separate, secure space in Copilot, aiming to produce what the company calls a coherent story of a user's health.",src:"Microsoft",url:"https://www.microsoft.com/en-us/microsoft-copilot/blog/2026/05/29/copilot-health-now-in-preview/"},
  {date:"2026-03-15",cat:"Research",title:"SAGE: Sensor-Augmented Grounding Engine for LLM-Powered Sleep Care Agent",desc:"arXiv preprint presenting SAGE, a sensor-augmented grounding engine that bridges the Data-Action Gap in sleep care by grounding LLM agents in personal wearable data. SAGE addresses the limitation that static dashboards lack context, rule-based agents rely on rigid scripts, and LLM agents without grounding lack trust. Preprint, not peer-reviewed.",src:"arXiv",url:"https://arxiv.org/abs/2604.16342"},
  {date:"2026-03-12",cat:"Product",title:"Microsoft Launches Copilot Health",desc:"Microsoft launched Copilot Health, a dedicated and isolated space within Copilot that brings together wearable data, electronic health records and lab results to deliver personalised health insights. An analysis of more than 500,000 de-identified Copilot conversations from January 2026 found nearly one in five involved personal symptom assessment or condition discussion - evidence of how much consumer demand already flows through general assistants.",src:"Microsoft / Fortune",url:"https://fortune.com/2026/03/12/microsoft-copilot-health-ai-medical-personal-health-data/"},
  {date:"2026-02-15",cat:"Product",title:"Oura Launches a Dedicated Reproductive Health AI Model",desc:"Oura released an AI model focused on women's health spanning menstrual cycles through menopause, alongside Oura Advisor, which turned a one-way insight feed into a two-way coaching dialogue. Analysts framed it as evidence that device makers are competing on interpretation and coaching rather than raw metrics.",src:"Sahha",url:"https://sahha.ai/blog/ai-health-coaching-platforms/"},
  {date:"2026-03-12",cat:"Product",title:"Verily Launches Verily Me Consumer Health App with AI Symptom Navigation",desc:"Verily, Alphabet's precision health company, announced general availability of its Verily Me consumer app at SXSW 2026, with AI-guided symptom navigation, personalized health recommendations from licensed clinicians, and deeper nutrition insights. Vendor claim: consumer wellness tool, not a medical device.",src:"Verily",url:"https://verily.com/newsroom/verily-me-adds-new-features-offering-a-safe-and-private-space-to-check-symptoms-and-make-sense-of-health"},
  {date:"2026-01-06",cat:"Regulatory",title:"FDA Eases Oversight of Wearables and AI-Enabled Devices",desc:"The FDA announced sweeping changes to digital health oversight, easing regulation of AI-enabled devices and wearables and revising general wellness and clinical decision support guidance. Software involving medical image or in vitro diagnostic signal processing remains in the device category, and the agency signalled it would cut the number of digital health guidance documents substantially while drafting a new AI framework. For consumer health agents, this widens the wellness lane - and sharpens the question of when advice becomes a medical claim.",src:"STAT News",url:"https://www.statnews.com/2026/01/06/fda-pulls-back-oversight-ai-enabled-devices-wearables/"},
  {date:"2026-01-15",cat:"Research",title:"Transforming Wearable Data into Personal Health Insights Using LLM Agents",desc:"Nature Communications published an LLM agent framework for making sense of wearable streams, arguing that complex numerical and temporal reasoning is beyond conventional language models and requires an agentic approach that iterates over tools and data.",src:"Nature Communications",url:"https://www.nature.com/articles/s41467-025-67922-y"},
  {date:"2026-04-10",cat:"Research",title:"Mount Sinai's AI Triage: 88-96% Concordance with Physician Triage",desc:"Mount Sinai published results for its 'Check Symptoms & Get Care' digital triage deployment, reporting blinded clinician comparison and continuous post-deployment review showing 88% to 96% concordance with physician triage, plus a tiered roadmap for organisations of different sizes. A companion peer-reviewed analysis examined triage concordance by patient authentication status.",src:"NEJM Catalyst",url:"https://catalyst.nejm.org/doi/full/10.1056/CAT.25.0394"},
  {date:"2026-03-20",cat:"Research",title:"Symptom Checker Triage Accuracy: Decade of Evidence Reviewed",desc:"A review of a decade of symptom-checker research found top-performing AI symptom checkers reaching roughly 82-88% accuracy in triaging patients to the correct care level, with a consistent tendency across ChatGPT versions to overtriage rather than undertriage - a safer failure direction, but one that consumes clinical capacity.",src:"Future Wellness Tech",url:"https://futurewellnesstech.com/ai-symptom-checkers-triage-accuracy-2026/"},
  {date:"2026-02-10",cat:"Research",title:"AI Symptom Checker Outperforms Junior Clinicians at Emergency Triage",desc:"A multicentre study across three Swedish hospitals validated an AI triage system in nearly 3,000 real-world emergency department cases. The model outperformed junior clinicians at identifying patients requiring emergency care across multiple clinical scenarios, while the authors emphasised that vitals-based scoring complements rather than replaces clinical assessment.",src:"2 Minute Medicine",url:"https://www.2minutemedicine.com/ai-symptom-checker-could-help-emergency-doctors-prioritize-patients/"},
  {date:"2026-02-24",cat:"Research",title:"ChatGPT Health Undertriages 52% of Emergency Cases in Structured Stress Test",desc:"Mount Sinai researchers tested ChatGPT Health's triage with 60 clinician-authored vignettes across 21 clinical domains under 16 factorial conditions (960 total responses). The system undertriaged 52% of gold-standard emergencies, directing diabetic ketoacidosis and impending respiratory failure to 24-48h evaluation instead of the ED. Crisis-intervention messages for suicidal ideation activated unpredictably. When family or friends minimized symptoms, triage shifted significantly toward less urgent care (OR 11.7, 95% CI 3.7-36.6). No significant race or sex effects, though CIs did not exclude meaningful differences. Published in Nature Medicine.",src:"Nature Medicine",url:"https://www.nature.com/articles/s41591-026-04297-7"},
  {date:"2026-02-09",cat:"Research",title:"Oxford Study: LLMs Excel on Tests But Fail Real Users Seeking Medical Advice",desc:"The largest randomised user study of LLMs for consumer medical advice, led by the Oxford Internet Institute and Nuffield Department of Primary Care Health Sciences in partnership with MLCommons, tested GPT-4o, Llama 3 and Command R+ with 1,298 UK participants across 10 medical scenarios. LLMs alone identified conditions in 94.9% of cases and chose the right disposition in 56.3%. But participants using the same LLMs identified conditions in fewer than 34.5% of cases and chose the right action in fewer than 44.2% - no better than a control group using ordinary search. The gap traced to conversational breakdown: users omitted details the model needed, and responses mixed good and poor advice. The authors recommend systematic human user testing before public deployment in healthcare.",src:"Nature Medicine / Oxford",url:"https://www.nature.com/articles/s41591-025-04074-y"},
  {date:"2026-02-01",cat:"Regulatory",title:"States Raise the Privacy Ceiling for Consumer Health AI",desc:"Analysis of the 2026 privacy landscape found California and Washington requiring detailed written consent for AI tools processing health data, with Colorado's SB 21-169 creating obligations for developers and deployers of high-risk AI in insurance. HIPAA still sets the floor for covered entities; consumer health agents operating outside it face the FTC Health Breach Notification Rule and a patchwork of stricter state law.",src:"blueBriX",url:"https://bluebrix.health/articles/ai-reset-a-new-era-for-healthcare-policy"},
  {date:"2026-01-20",cat:"Research",title:"AI Coaching Trial and the Interpretation Gap",desc:"Reviewing the AI health coaching market, analysts noted that Google, Oura and WHOOP had all launched coaches powered by wearable data and LLMs, and cited a randomised clinical trial of AI coaching while pointing to the same core problem quantified by SensorFM: users do not know what to do with hundreds of daily data points - they want a decision, not a dashboard.",src:"Sahha",url:"https://sahha.ai/blog/ai-health-coaching-platforms/"},
  {date:"2025-11-10",cat:"Product",title:"Apple's AI Health Service Reported for 2026 (Project Mulberry)",desc:"Bloomberg reported that Apple still planned an AI-powered Health+ service for 2026, following internal work on an AI health coach widely reported under the codename Project Mulberry. The effort was later described as scaled back, with nutrition tracking and a reduced AI health agent arriving first.",src:"MacRumors",url:"https://www.macrumors.com/2025/11/10/ai-apple-health-service-still-coming/"},
  {date:"2026-06-15",cat:"Competitor",title:"Wearable Makers Push Toward Clinical Claims",desc:"Coverage of wearable makers noted WHOOP, Oura, Apple and a new wave of challengers layering blood pressure monitoring, metabolic insights and AI-generated guidance on top of hardware - narrowing the gap between a wellness feature and a clinical claim, with regulators watching and at least one vendor publicly disputing an interpretation of its own feature.",src:"Athletech News",url:"https://athletechnews.com/wearable-makers-eye-healthcare-new-innovations-apple-watch-oura-whoop-garmin/"},
  {date:"2026-09-01",cat:"Metric",title:"FDA Has Authorised 1,600+ AI-Enabled Medical Devices",desc:"The FDA reported more than 1,600 AI-enabled medical devices authorised for US marketing as of September 2026, up from 1,524 in March 2026 - almost entirely Class II 510(k) clearances, with radiology still about three-quarters of the list. The count sits alongside the January 2026 relaxation of general wellness and CDS oversight, defining two very different lanes for consumer versus clinical AI.",src:"FDA",url:"https://www.fda.gov/medical-devices/digital-health-center-excellence/artificial-intelligence-enabled-medical-devices"},
  {date:"2026-08-27",cat:"Research",title:"SuperSenseDoctor: Multimodal Contactless Agent for Health Tracking via WiFi, Radar and Thermal Sensing",desc:"arXiv preprint presenting a contactless agent architecture for long-term home health monitoring. The system transforms WiFi, mmWave radar, and surface temperature into a persistent human health state, using fixed decision rules for daily monitoring and event-driven reasoning for anomalies. Achieves 1.994 bpm MAE for heart rate, 0.197 bpm MAE for respiratory rate, and 96.5% fall-recognition accuracy. Evaluated across 2,686 one-second states with a 96.7% checklist pass rate. Demonstrates feasibility of a stateful sensing-to-action loop for ambient home health monitoring.",src:"arXiv",url:"https://arxiv.org/abs/2609.16257"},
  {date:"2026-08-18",cat:"Regulatory",title:"FDA Publishes Discussion Paper on Regulation of Generative AI-Enabled Medical Devices",desc:"The FDA's Digital Health Center of Excellence published a discussion paper on considerations for regulating GenAI-enabled medical devices, covering risk assessment, premarket evaluation, postmarket monitoring, and other regulatory topics. The paper seeks stakeholder feedback on the unique risks posed by GenAI compared to traditional AI-enabled devices. Feedback deadline was October 19, 2026. The paper is for discussion purposes only and does not represent draft or final guidance.",src:"FDA",url:"https://www.fda.gov/medical-devices/digital-health-center-excellence/considerations-regulation-generative-ai-enabled-medical-devices-discussion-paper-and-request"},
  {date:"2026-08-11",cat:"Research",title:"ECHO: Locally-Deployable Agentic Health Assistant with Temporal Memory and Safety Guardrails",desc:"arXiv preprint from Istanbul Technical University presenting ECHO (Enhanced Care & Health Observer), a locally-deployable conversational health assistant for chronic care management. Built on a ReAct loop with LangGraph, 17 clinical tools, and a temporal knowledge graph for cross-session memory. A two-stage hybrid safety layer combines rule-based crisis detection with a graph neural network achieving 88.8% accuracy and 90.6% unsafe recall. Runs entirely on consumer hardware with no external data transmission, supporting GDPR compliance. Achieves 94.9% tool-execution pass rate across 59 scenarios.",src:"arXiv",url:"https://arxiv.org/abs/2608.06110"},
  {date:"2026-06-16",cat:"Research",title:"RubricsTree: Scalable Evaluation Framework for Personal Health Agents",desc:"Google Research introduced RubricsTree, a scalable evaluation framework with over 100 atomic, clinically-verifiable Boolean rubrics evolved from 4,000 real user queries through an iterative human-in-the-loop curation protocol. A context-aware adaptive router activates only relevant rubric subsets per query. When used for performance optimization, RubricsTree yields up to ~66% relative gains on HealthBench for Gemini, GPT, and Qwen model families. Addresses the evaluation bottleneck where physician annotation is reliable but costly, while LLM-as-a-judge evaluators are scalable but clinically misaligned.",src:"arXiv / Google Research",url:"https://arxiv.org/abs/2606.18203"},
  {date:"2026-05-10",cat:"Research",title:"SymptomAI: Google's Conversational AI Agent for Everyday Symptom Assessment Deployed in Fitbit",desc:"Google Research deployed SymptomAI, a conversational AI agent for end-to-end patient interviewing and differential diagnosis, via the Fitbit app in a study randomising 13,917 participants across five AI agent configurations. SymptomAI's differential diagnoses were significantly more accurate than independent clinicians given the same dialogue (OR=2.56, p<0.001) in a blinded randomised comparison. Agentic strategies conducting a dedicated symptom interview substantially outperformed user-guided conversations (p<0.001). The study used SymptomAI diagnoses as labels to analyse over 500,000 days of wearable metrics across nearly 400 conditions, finding strong associations between acute infections and physiological shifts (e.g., OR>7 for influenza). Limited by self-reported ground truth.",src:"arXiv / Google Research",url:"https://arxiv.org/abs/2605.04012"},
  {date:"2026-04-30",cat:"Research",title:"Safety Evaluation of a Generative AI Agent for Anxiety and Depression Symptoms",desc:"A preprint evaluating the safety of a clinician-designed generative AI care agent for anxiety and depression using a scalable dual-methods paradigm: high-throughput in silico simulation paired with continuous real-world monitoring. The digital program delivered structured cognitive behavioural skills training through the AI agent. The evaluation paradigm addresses the challenge that conventional one-off evaluation approaches cannot fully address the probabilistic nature and rapid model iteration of generative AI in mental health.",src:"OSF Preprints",url:"https://doi.org/10.31234/osf.io/8kvm6_v2"},
  {date:"2026-04-21",cat:"Research",title:"Safety, Hallucination, and Failure Modes in Agentic Health AI: A State-of-the-Art Review",desc:"A systematic literature review of safety issues in agentic AI systems deployed in clinical environments. Unlike conventional single-turn AI tools, agentic systems autonomously plan multistep tasks, invoke external tools, retain memory, and pursue clinical goals with minimal human intervention, introducing a qualitatively distinct safety profile. The review covers hallucination, tool misuse, memory corruption, and escalation failures across radiology, clinical decision support, intensive care monitoring, drug discovery, and patient-facing care.",src:"Preprints.org",url:"https://doi.org/10.20944/preprints202604.1409.v1"}
];
